mapper.select:
SELECT * FROM fault_tree_versions
WHERE tree_id = #{treeId}
ORDER BY version_number DESC

mapper.delete:
DELETE FROM fault_tree_versions
WHERE tree_id = #{treeId}
AND id NOT IN (
    SELECT id FROM fault_tree_versions
    WHERE tree_id = #{treeId}
    ORDER BY version_number DESC
    FETCH FIRST #{deleteCount} ROWS ONLY
)
